\subsection{Assumptions}

\begin{proposition}[Asymptotic exactness of iterates] \label{prop:parameter_gap_decay}
	Suppose \ref{assumption:A1}-\ref{assumption:A4} hold. Then for each $i=1,\dots,m$, 
	\begin{align}\label{eq:parameter_gap_decay}
		\lVert \theta_{n}^{(i)} - \theta_{n}^{(i\star)} \rVert = o(1),
	\end{align}
\end{proposition}

\item[(a)] (\textit{Trust-region used}) \,\,  If $\sum_{n=1}^{\infty} r_{n}^{2}<\infty$, then $r_{n+1}/r_{n}=O(1)$; 

\item[(b)] (\textit{Trust-region not used}) \,\,  If $r_{n}\equiv \infty$, then surrogates  $g_{n}^{(i)}$ for all $n,i$ have $L_{g}$-Lipschitz contiuous gradients  for some constant $L_{g}>0$ and are $\lambda$-strongly convex  for some constant $\lambda>0$: For all $\theta,\theta^{*}\in \Theta^{(i)}$, 
\begin{align}
\textup{(Lipschitz gradients)}\hspace{3cm}	\lVert \nabla g_{n}^{(i)}(\theta) - \nabla g_{n}^{(i)}(\theta^{*})   \rVert &\le L_{g} \lVert \theta-\theta^{*} \rVert,\label{eq:surrogate_L_smoothness} \\
\textup{(Strong convexity)}\hspace{1.03cm}	g_{n}^{(i)}(\theta) - g_{n}^{(i)}(\theta^{*}) - \langle \nabla g_{n}^{(i)}(\theta^{*}),\, \theta-\theta^{*} \rangle &\ge \frac{\lambda}{2}\lVert \theta - \theta^{*}\rVert^{2}. \label{eq:surrogate_strong_convexity}
\end{align}
